import pandas as pd
import pytest

def calcula_total(df: pd.DataFrame) -> pd.DataFrame:
    return df.groupby("id_cliente", as_index=False)["valor"].sum()

@pytest.mark.parametrize("entrada,esperado", [
    ([(1, 10.0), (1, 5.0), (2, 3.0)], {1: 15.0, 2: 3.0}),
    ([], {}),
])
def test_calcula_total(entrada, esperado):
    df = pd.DataFrame(entrada, columns=["id_cliente", "valor"])
    res = calcula_total(df)
    assert dict(zip(res["id_cliente"], res["valor"])) == esperado

